import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"表结构升级","description":"","frontmatter":{},"headers":[],"relativePath":"backend/upgrade.md","filePath":"backend/upgrade.md","lastUpdated":1794298628000}`),a={name:`backend/upgrade.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="表结构升级" tabindex="-1">表结构升级 <a class="header-anchor" href="#表结构升级" aria-label="Permalink to “表结构升级”">​</a></h1><p>本页说明正式库的表结构如何建立与升级、升级脚本怎么写，以及版本与升级记录的查看方式，适用于部署人员与修改实体的后端开发者。</p><p>开发库与正式库建表的方式不同：</p><table tabindex="0"><thead><tr><th>库</th><th>建表方式</th></tr></thead><tbody><tr><td>开发库</td><td>Development 打开 <code>XiHan:Persistence:SqlSugar:InitTables</code>，启动时按实体建缺表、加缺列（另补软删除实体的部分唯一索引）</td></tr><tr><td>正式库</td><td>只认 <code>Schema/&lt;版本&gt;/*.sql</code> 与版本台账，由 <code>SchemaUpgrader</code> 执行；<code>InitTables</code> 保持关闭</td></tr></tbody></table><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to “机制”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>脚本</td><td><code>backend/src/XiHan.BasicApp.Host/Schema/&lt;版本&gt;/*.sql</code>：每个子目录是一个版本（<code>主.次.修订</code>，目录名不是版本号即报错），PostgreSQL 方言、<code>CREATE TABLE IF NOT EXISTS</code> 风格、可重复执行；目录里的 <code>.sql</code> 按文件名顺序执行。目录可用 <code>BasicApp:Schema:Directory</code> 改（相对路径按程序目录解析）</td></tr><tr><td>基线</td><td>最低的版本目录：<code>Schema/6.0.0/0001-baseline.sql</code>，由 <code>SchemaBaselineTests</code> 按 InitTables 建出的结构生成，包含应用实体与框架 Provider 的表（<code>tenant_record</code>、<code>permission_grant_record</code>、<code>audit_record</code>、<code>message_translation</code>、<code>outbox_message</code>、调度五张表、工作流九张表）</td></tr><tr><td>台账</td><td>每个库自己的 <code>sys_version</code>（结构版本、应用版本、是否升级中、升级节点与开始时间）与 <code>sys_migration_history</code>（每个脚本的执行记录：版本、脚本、节点、成败、耗时、错误）</td></tr><tr><td>执行器</td><td>Runtime 的 <code>SchemaUpgrader</code>，租户独立库由 <code>TenantSchemas</code> 升级</td></tr></tbody></table><h3 id="执行顺序" tabindex="-1">执行顺序 <a class="header-anchor" href="#执行顺序" aria-label="Permalink to “执行顺序”">​</a></h3><ol><li>打开 <code>BasicApp:Schema:CreateDatabase</code>（开发环境打开，缺省关）时，平台库不存在即先建库；台账两张表再按实体建好；</li><li>经台账行的条件更新抢升级锁（时间按库的 <code>now()</code>，各节点时钟不必对齐）；锁过了 <code>BasicApp:Schema:LockExpiryMinutes</code>（缺省 30 分钟）即视为持锁节点已退出，别的节点可以接手；等别的节点升级最多 <code>LockWaitMinutes</code>（缺省 10 分钟），等不到即升级失败；</li><li>新库从基线建起，之后每个版本一个目录，只执行比台账新的；每个脚本一个事务，成功与失败都记进升级记录，失败即停；库的结构版本比应用带的脚本还新即 <code>RUNTIME_VALIDATION_004</code>（不能用旧版本的应用连新库）；</li><li>平台库升完后，在同一把锁里逐个升级已就绪的租户独立库：只跑 <code>Schema/&lt;版本&gt;/tenant/*.sql</code>，台账在各自的库里，停用的租户也升；没有租户脚本的版本只推进台账。</li></ol><p>升级期间，已在运行的其他节点每 10 秒读一次台账，看到有节点持着没过期的锁即进入维护模式：除 <code>/health</code> 与 <code>/.well-known/</code> 外一律 503（<code>RUNTIME_UNAVAILABLE_003</code>，带 <code>Retry-After</code>）。</p><p>只支持 PostgreSQL：别的库（测试用的 SQLite）跳过脚本，由 InitTables 建表。</p><h3 id="执行时机" tabindex="-1">执行时机 <a class="header-anchor" href="#执行时机" aria-label="Permalink to “执行时机”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>启动时</td><td><code>BasicApp:Schema:AutoUpgrade</code>（缺省 <code>true</code>）：开始监听之前执行，升完前这个节点不接请求；失败即以日志 <code>Startup aborted: schema upgrade failed</code> 中断启动</td></tr><tr><td>命令</td><td><code>XiHan.BasicApp.Host schema upgrade</code>：不启动应用（Feature 一启动就要读写自己的表，新库上升级要排在它们之前），执行后以 JSON 输出报告（<code>from</code>、<code>to</code>、<code>applied</code>），失败即非零退出；关掉 <code>AutoUpgrade</code> 时由运维先跑它再启动</td></tr></tbody></table><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend/src/XiHan.BasicApp.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch-profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Development</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>新库按「<code>schema upgrade</code>（或带 <code>AutoUpgrade</code> 启动一次）→ <code>seed [--only &lt;名,...&gt;] [--list]</code>」初始化，见<a href="./../deployment#首次初始化">部署</a>。脚本由执行器按台账执行，不要手工对库跑。</p><h3 id="租户独立库" tabindex="-1">租户独立库 <a class="header-anchor" href="#租户独立库" aria-label="Permalink to “租户独立库”">​</a></h3><p><code>tenants.initialize-database</code> 在租户的分片上建库、只建租户库实体的表（按当前实体建即是最新结构），并在该库的台账登记当前结构版本；之后随平台的升级只跑 <code>tenant/</code> 下的脚本。见<a href="./multi-tenancy#开通三步">多租户 SaaS</a>。</p><h2 id="写升级脚本" tabindex="-1">写升级脚本 <a class="header-anchor" href="#写升级脚本" aria-label="Permalink to “写升级脚本”">​</a></h2><p>改了实体（加表、加列、改长度）时：</p><ol><li>首个正式版发布之前，直接重生成基线：设 <code>XIHAN_TEST_POSTGRES</code>（服务器连接串，不带库名）与 <code>XIHAN_UPDATE_SCHEMA_BASELINE=1</code> 跑 <code>SchemaBaselineTests.Baseline_BuildsTheSameTablesAsInitTables_AndRunsOnce</code>，测试自建临时库、按 InitTables 写回 <code>0001-baseline.sql</code>，再校验基线建出的库与 InitTables 一致；只提交基线里属于本次改动的变化。</li><li>正式版发布之后，每个版本一个新目录（<code>Schema/&lt;新版本&gt;/</code>），新增脚本、文件名带序号： <ul><li>写成可重复执行（<code>CREATE TABLE IF NOT EXISTS</code>、<code>ADD COLUMN IF NOT EXISTS</code> …），只用 PostgreSQL 方言；</li><li>影响租户库实体的，另在 <code>Schema/&lt;新版本&gt;/tenant/</code> 写一份。</li></ul></li><li>开发库由 InitTables 自动对齐，但正式环境只执行脚本，两者必须一致，<code>SchemaBaselineTests</code> 守着基线与实体的一致性。</li></ol><div class="tip custom-block"><p class="custom-block-title">给已有行的表加列</p><p>开发库的 InitTables 只能给已有行的表加可空列，或数值 / 枚举 / 布尔 / <code>Guid</code> 这类能按 CLR 缺省值回填的非可空列；非可空的字符串与日期时间列在实体里声明成可空，或者重建开发库。</p></div><div class="tip custom-block"><p class="custom-block-title">新的唯一索引建不出来</p><p>实体或框架的表多了唯一索引时，开发库里已有重复数据会让 InitTables 建不出索引，宿主启动即失败。开发库重建后重新 <code>seed</code>，或按报错的表去掉重复行再启动。</p></div><h2 id="版本与升级记录" tabindex="-1">版本与升级记录 <a class="header-anchor" href="#版本与升级记录" aria-label="Permalink to “版本与升级记录”">​</a></h2><p>Maintenance 包提供只读的管理面（平台侧，页面在「系统管理 › 系统服务」下）：</p><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>versions.list</code> / <code>get</code></td><td><code>maintenance.versions.read</code></td><td>每个库一行（平台库为 <code>platform</code>，另加各独立库租户，按库名取）：应用版本、结构版本、是否升级中、升级节点；读不到的库带错误说明</td></tr><tr><td><code>migrations.list</code> / <code>get</code></td><td><code>maintenance.migrations.read</code></td><td>脚本执行台账：版本、脚本、节点、成败、耗时</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./database">数据库配置</a> · <a href="./../deployment">部署</a> · <a href="./health-observability">健康与可观测性</a></li></ul>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};